/* D8 seedable deterministic PRNG (xoshiro256**). State = a 32-byte NOVA-managed `bytes` (4x u64 LE), so it
 * is GC/RC-tracked (no leak, no raw-pointer confusion). rng_new(seed) seeds via splitmix64; rng_next advances
 * the state IN PLACE (bytes are ref-semantic). Distinct API from the non-deterministic random_* (CSPRNG). */
static inline uint64_t nova_rng_rd(int64_t st, int i) {
    uint64_t v = 0;
    for (int j = 0; j < 8; j++) v |= ((uint64_t)(nova_rt_bytes_get(st, (int64_t)(i * 8 + j)) & 0xFF)) << (j * 8);
    return v;
}
static inline void nova_rng_wr(int64_t st, int i, uint64_t v) {
    for (int j = 0; j < 8; j++) nova_rt_bytes_set(st, (int64_t)(i * 8 + j), (int64_t)((v >> (j * 8)) & 0xFF));
}
static inline uint64_t nova_rng_rotl(uint64_t x, int k) { return (x << k) | (x >> (64 - k)); }
int64_t nova_rt_rng_new(int64_t seed) {
    int64_t st = nova_rt_bytes_create(32);
    uint64_t sm = (uint64_t)seed;
    for (int i = 0; i < 4; i++) {
        uint64_t z = (sm += 0x9E3779B97F4A7C15ULL);
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
        z = z ^ (z >> 31);
        nova_rng_wr(st, i, z);
    }
    return st;
}
int64_t nova_rt_rng_next(int64_t st) {
    uint64_t s0 = nova_rng_rd(st, 0), s1 = nova_rng_rd(st, 1), s2 = nova_rng_rd(st, 2), s3 = nova_rng_rd(st, 3);
    uint64_t result = nova_rng_rotl(s1 * 5, 7) * 9;
    uint64_t t = s1 << 17;
    s2 ^= s0; s3 ^= s1; s1 ^= s2; s0 ^= s3; s2 ^= t; s3 = nova_rng_rotl(s3, 45);
    nova_rng_wr(st, 0, s0); nova_rng_wr(st, 1, s1); nova_rng_wr(st, 2, s2); nova_rng_wr(st, 3, s3);
    return (int64_t)result;
}
int64_t nova_rt_rng_int(int64_t st, int64_t n) {
    if (n <= 0) return 0;
    uint64_t r = (uint64_t)nova_rt_rng_next(st);
    return (int64_t)(r % (uint64_t)n);
}
int64_t nova_rt_rng_float(int64_t st) {
    uint64_t r = (uint64_t)nova_rt_rng_next(st);
    double d = (double)(r >> 11) * (1.0 / 9007199254740992.0);
    return f2i(d);
}
int64_t nova_rt_pi(void) { return f2i(3.14159265358979323846); }
int64_t nova_rt_e(void)  { return f2i(2.71828182845904523536); }
int64_t nova_rt_gcd(int64_t a, int64_t b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) { int64_t t = b; b = a % b; a = t; }
    return a;
}
int64_t nova_rt_lcm(int64_t a, int64_t b) {
    if (a == 0 || b == 0) return 0;
    int64_t g = nova_rt_gcd(a, b);
    int64_t r = (a / g) * b;
    return r < 0 ? -r : r;
}

/* ── Bit manipulation (single hardware instructions on every target) ───────────
   All operate on the 64-bit two's-complement representation. clz/ctz of 0 are
   UB for the __builtin_* intrinsics, so they are guarded to return 64; rotates
   mask the count to 0..63 and use the (64-r)&63 trick so rot-by-0 is never a
   shift-by-64 (which is also UB). */
int64_t nova_rt_popcount(int64_t x) {
    return (int64_t)__builtin_popcountll((unsigned long long)x);
}
int64_t nova_rt_clz(int64_t x) {
    if (x == 0) return 64;
    return (int64_t)__builtin_clzll((unsigned long long)x);
}
int64_t nova_rt_ctz(int64_t x) {
    if (x == 0) return 64;
    return (int64_t)__builtin_ctzll((unsigned long long)x);
}
int64_t nova_rt_rotl(int64_t x, int64_t n) {
    unsigned long long v = (unsigned long long)x;
    unsigned r = (unsigned)(((unsigned long long)n) & 63ULL);
    return (int64_t)((v << r) | (v >> ((64 - r) & 63)));
}
int64_t nova_rt_rotr(int64_t x, int64_t n) {
    unsigned long long v = (unsigned long long)x;
    unsigned r = (unsigned)(((unsigned long long)n) & 63ULL);
    return (int64_t)((v >> r) | (v << ((64 - r) & 63)));
}

/* ── Network byte order (cat-13): host<->network (big-endian) conversion for raw
   protocol code. On a little-endian host these byte-swap; on big-endian they are
   identity. Endianness is detected at runtime and __builtin_bswap is used, so no
   <arpa/inet.h>/<winsock2.h> dependency (portable Linux/Windows). ntoh* == hton*
   (the conversion is its own inverse). Inputs are taken as unsigned 16/32-bit
   (upper i64 bits ignored); outputs are zero-extended. */
static int nova_is_big_endian(void) { uint16_t t = 1; return ((const unsigned char*)&t)[0] == 0; }
int64_t nova_rt_htons(int64_t v) {
    uint16_t x = (uint16_t)((uint64_t)v & 0xFFFFu);
    if (!nova_is_big_endian()) x = __builtin_bswap16(x);
    return (int64_t)x;
}
int64_t nova_rt_ntohs(int64_t v) { return nova_rt_htons(v); }
int64_t nova_rt_htonl(int64_t v) {
    uint32_t x = (uint32_t)((uint64_t)v & 0xFFFFFFFFu);
    if (!nova_is_big_endian()) x = __builtin_bswap32(x);
    return (int64_t)x;
}
int64_t nova_rt_ntohl(int64_t v) { return nova_rt_htonl(v); }

/* ── UTF-8 / Unicode (codepoint-aware; complements byte-level len/ord/chr) ──────
   These ADD codepoint semantics without changing the existing byte-based ops, so
   no existing program changes behavior. A NOVA string is UTF-8 bytes. */
static int64_t nova_utf8_decode(const unsigned char* s, size_t len, size_t* i) {
    if (*i >= len) return -1;
    unsigned char b0 = s[*i];
    if (b0 < 0x80) { (*i)++; return (int64_t)b0; }
    int n; int64_t cp;
    if      ((b0 & 0xE0) == 0xC0) { n = 1; cp = b0 & 0x1F; }
    else if ((b0 & 0xF0) == 0xE0) { n = 2; cp = b0 & 0x0F; }
    else if ((b0 & 0xF8) == 0xF0) { n = 3; cp = b0 & 0x07; }
    else return -1;                       /* invalid lead byte */
    if (*i + (size_t)n >= len) return -1; /* truncated sequence */
    for (int k = 1; k <= n; k++) {
        unsigned char b = s[*i + (size_t)k];
        if ((b & 0xC0) != 0x80) return -1;
        cp = (cp << 6) | (b & 0x3F);
    }
    *i += (size_t)(n + 1);
    return cp;
}
static int nova_utf8_encode(int64_t cp, char* out) {
    if (cp < 0 || cp > 0x10FFFF) return 0;
    if (cp < 0x80) { out[0] = (char)cp; return 1; }
    if (cp < 0x800) { out[0] = (char)(0xC0 | (cp >> 6)); out[1] = (char)(0x80 | (cp & 0x3F)); return 2; }
    if (cp < 0x10000) { out[0] = (char)(0xE0 | (cp >> 12)); out[1] = (char)(0x80 | ((cp >> 6) & 0x3F)); out[2] = (char)(0x80 | (cp & 0x3F)); return 3; }
    out[0] = (char)(0xF0 | (cp >> 18)); out[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
    out[2] = (char)(0x80 | ((cp >> 6) & 0x3F)); out[3] = (char)(0x80 | (cp & 0x3F)); return 4;
}
int64_t nova_rt_char_count(int64_t s_val) {
    const unsigned char* s = (const unsigned char*)nova_str_safe(s_val);
    if (!s) return 0;
    size_t len = strlen((const char*)s), i = 0; int64_t count = 0;
    while (i < len) { size_t j = i; int64_t cp = nova_utf8_decode(s, len, &j); if (cp < 0) i++; else i = j; count++; }
    return count;
}
int64_t nova_rt_char_at(int64_t s_val, int64_t index) {
    const unsigned char* s = (const unsigned char*)(uintptr_t)s_val;
    if (!s || index < 0) return (int64_t)(uintptr_t)nova_fat_str_create("", 0);
    size_t len = strlen((const char*)s), i = 0; int64_t idx = 0;
    while (i < len) {
        size_t j = i; int64_t cp = nova_utf8_decode(s, len, &j);
        size_t adv = (cp < 0) ? 1 : (j - i);
        if (idx == index) return (int64_t)(uintptr_t)nova_fat_str_create((const char*)s + i, adv);
        i += adv; idx++;
    }
    return (int64_t)(uintptr_t)nova_fat_str_create("", 0);
}
int64_t nova_rt_code_points(int64_t s_val) {
    const unsigned char* s = (const unsigned char*)(uintptr_t)s_val;
    int64_t list = nova_rt_list_create();
    if (!s) return list;
    size_t len = strlen((const char*)s), i = 0;
    while (i < len) {
        size_t j = i; int64_t cp = nova_utf8_decode(s, len, &j);
        if (cp < 0) { cp = (int64_t)s[i]; i++; } else i = j;
        nova_rt_list_append(list, cp);
    }
    return list;
}
int64_t nova_rt_from_codepoint(int64_t cp) {
    char out[5]; int n = nova_utf8_encode(cp, out);
    if (n == 0) return (int64_t)(uintptr_t)nova_fat_str_create("", 0);
    return (int64_t)(uintptr_t)nova_fat_str_create(out, (size_t)n);
}
