int64_t nova_rt_str_hex_encode(int64_t val) {
    const char* s = nova_str_safe(val);
    size_t len = strlen(s);
    char* buf = (char*)malloc(len * 2 + 1);
    if (!buf) return nova_rt_create_string("");
    for (size_t i = 0; i < len; i++) {
        unsigned char c = (unsigned char)s[i];
        buf[i*2]   = "0123456789abcdef"[c >> 4];
        buf[i*2+1] = "0123456789abcdef"[c & 0xF];
    }
    buf[len*2] = '\0';
    int64_t r = nova_rt_create_string(buf);
    free(buf);
    return r;
}

int64_t nova_rt_str_hex_decode(int64_t val) {
    const char* s = nova_str_safe(val);
    size_t len = strlen(s);
    if (len % 2 != 0) return nova_rt_create_string("");
    size_t out_len = len / 2;
    char* buf = (char*)malloc(out_len + 1);
    if (!buf) return nova_rt_create_string("");
    for (size_t i = 0; i < out_len; i++) {
        unsigned char hi, lo;
        char ch = s[i*2];
        char cl = s[i*2+1];
        if (ch >= '0' && ch <= '9') hi = (unsigned char)(ch - '0');
        else if (ch >= 'a' && ch <= 'f') hi = (unsigned char)(ch - 'a' + 10);
        else if (ch >= 'A' && ch <= 'F') hi = (unsigned char)(ch - 'A' + 10);
        else { free(buf); return nova_rt_create_string(""); }
        if (cl >= '0' && cl <= '9') lo = (unsigned char)(cl - '0');
        else if (cl >= 'a' && cl <= 'f') lo = (unsigned char)(cl - 'a' + 10);
        else if (cl >= 'A' && cl <= 'F') lo = (unsigned char)(cl - 'A' + 10);
        else { free(buf); return nova_rt_create_string(""); }
        buf[i] = (char)((hi << 4) | lo);
    }
    buf[out_len] = '\0';
    int64_t r = nova_rt_create_string(buf);
    free(buf);
    return r;
}

int64_t nova_rt_list_zip3(int64_t a, int64_t b, int64_t c) {
    NovaList* la = nova_as_list(a);
    NovaList* lb = nova_as_list(b);
    NovaList* lc = nova_as_list(c);
    if (!la || !lb || !lc) return nova_rt_list_create();
    int64_t sz = la->size;
    if (lb->size < sz) sz = lb->size;
    if (lc->size < sz) sz = lc->size;
    int64_t out = nova_rt_list_create();
    for (int64_t i = 0; i < sz; i++) {
        int64_t triple = nova_rt_list_create();
        nova_rt_list_append(triple, la->data[i]);
        nova_rt_list_append(triple, lb->data[i]);
        nova_rt_list_append(triple, lc->data[i]);
        nova_rt_list_append(out, triple);
    }
    return out;
}

int64_t nova_rt_dict_merge_with(int64_t a, int64_t b, int64_t closure) {
    NovaDict* da = nova_as_dict(a);
    NovaDict* db = nova_as_dict(b);
    int64_t out = nova_rt_dict_create();
    int64_t* rec = (int64_t*)(uintptr_t)closure;
    typedef int64_t (*nova_fn2)(int64_t, int64_t, int64_t);
    nova_fn2 fn = (nova_fn2)(uintptr_t)rec[0];
    if (da) {
        for (int64_t i = 0; i < da->size; i++) {
            nova_rt_dict_set(out, da->keys[i], da->vals[i]);
        }
    }
    if (db) {
        for (int64_t i = 0; i < db->size; i++) {
            int64_t existing = nova_rt_dict_get(out, db->keys[i]);
            if (existing != 0) {
                int64_t merged = fn(closure, existing, db->vals[i]);
                nova_rt_dict_set(out, db->keys[i], merged);
            } else {
                nova_rt_dict_set(out, db->keys[i], db->vals[i]);
            }
        }
    }
    return out;
}

/* --- Batch 3: split-lines, join, levenshtein, sorted, dict reduce, cross product --- */

int64_t nova_rt_str_split_lines(int64_t val) {
    const char* s = nova_str_safe(val);
    int64_t out = nova_rt_list_create();
    const char* start = s;
    while (*s) {
        if (*s == '\n') {
            size_t len = (size_t)(s - start);
            if (len > 0 && start[len-1] == '\r') len--;
            char* buf = (char*)malloc(len + 1);
            if (buf) { memcpy(buf, start, len); buf[len] = '\0'; nova_rt_list_append(out, nova_rt_create_string(buf)); free(buf); }
            start = s + 1;
        }
        s++;
    }
    if (s > start) {
        size_t len = (size_t)(s - start);
        char* buf = (char*)malloc(len + 1);
        if (buf) { memcpy(buf, start, len); buf[len] = '\0'; nova_rt_list_append(out, nova_rt_create_string(buf)); free(buf); }
    }
    return out;
}

int64_t nova_rt_str_join_with(int64_t handle, int64_t sep) {
    NovaList* l = nova_as_list(handle);
    if (!l || l->size == 0) return nova_rt_create_string("");
    const char* sep_str = nova_str_safe(sep);
    size_t sep_len = strlen(sep_str);
    size_t total = 0;
    for (int64_t i = 0; i < l->size; i++) {
        total += strlen(nova_str_safe(l->data[i]));
        if (i > 0) total += sep_len;
    }
    char* buf = (char*)malloc(total + 1);
    if (!buf) return nova_rt_create_string("");
    char* p = buf;
    for (int64_t i = 0; i < l->size; i++) {
        if (i > 0) { memcpy(p, sep_str, sep_len); p += sep_len; }
        const char* s = nova_str_safe(l->data[i]);
        size_t slen = strlen(s);
        memcpy(p, s, slen); p += slen;
    }
    *p = '\0';
    int64_t r = nova_rt_create_string(buf);
    free(buf);
    return r;
}

int64_t nova_rt_str_levenshtein(int64_t a, int64_t b) {
    const char* sa = nova_str_safe(a);
    const char* sb = nova_str_safe(b);
    size_t la = strlen(sa), lb = strlen(sb);
    if (la == 0) return (int64_t)lb;
    if (lb == 0) return (int64_t)la;
    if (la > 1000) la = 1000;
    if (lb > 1000) lb = 1000;
    int64_t* prev = (int64_t*)malloc((lb + 1) * sizeof(int64_t));
    int64_t* curr = (int64_t*)malloc((lb + 1) * sizeof(int64_t));
    if (!prev || !curr) { free(prev); free(curr); return (int64_t)(la > lb ? la : lb); }
    for (size_t j = 0; j <= lb; j++) prev[j] = (int64_t)j;
    for (size_t i = 1; i <= la; i++) {
        curr[0] = (int64_t)i;
        for (size_t j = 1; j <= lb; j++) {
            int64_t cost = (sa[i-1] == sb[j-1]) ? 0 : 1;
            int64_t del = prev[j] + 1;
            int64_t ins = curr[j-1] + 1;
            int64_t rep = prev[j-1] + cost;
            int64_t m = del < ins ? del : ins;
            curr[j] = m < rep ? m : rep;
        }
        int64_t* tmp = prev; prev = curr; curr = tmp;
    }
    int64_t result = prev[lb];
    free(prev); free(curr);
    return result;
}

int64_t nova_rt_list_is_sorted(int64_t handle) {
    NovaList* l = nova_as_list(handle);
    if (!l || l->size <= 1) return 1;
    for (int64_t i = 1; i < l->size; i++) {
        if (l->data[i] < l->data[i-1]) return 0;
    }
    return 1;
}

int64_t nova_rt_dict_reduce(int64_t handle, int64_t init, int64_t closure) {
    NovaDict* d = nova_as_dict(handle);
    if (!d) return init;
    int64_t* rec = (int64_t*)(uintptr_t)closure;
    typedef int64_t (*nova_fn3)(int64_t, int64_t, int64_t, int64_t);
    nova_fn3 fn = (nova_fn3)(uintptr_t)rec[0];
    int64_t acc = init;
    for (int64_t i = 0; i < d->size; i++) {
        acc = fn(closure, acc, d->keys[i], d->vals[i]);
    }
    return acc;
}

